mapper.sql:
s.del_flag = '0'
and s.status = '0'
and t.del_flag = '0'
and t.status = '0'
and t.match_status = 'MATCHED'
and t.competition_role_name in ('队员', 'MEMBER', '选手', 'PLAYER')

    and s.competition_series_id = #{competitionSeriesId}


    and cs.competition_id = #{competitionId}


    and s.competition_track_id = #{competitionTrackId}


    and s.contest_start_time >= #{startTimeBegin}


    and s.contest_start_time <= #{startTimeEnd}


    and s.report_location like concat('%', #{checkinLocation}, '%')


    and s.schedule_id = #{scheduleId}

select v.*, coalesce(team_count.completed_team_count, 0) as completed_team_count, coalesce(team_count.partial_team_count, 0) as partial_team_count, coalesce(team_count.unsigned_team_count, 0) as unsigned_team_count from (
) v left join ( select tg.schedule_id, sum(case when tg.signed_person_count = tg.total_person_count and tg.total_person_count > 0 then 1 else 0 end) as completed_team_count, sum(case when tg.signed_person_count > 0 and tg.signed_person_count < tg.total_person_count then 1 else 0 end) as partial_team_count, sum(case when tg.signed_person_count = 0 then 1 else 0 end) as unsigned_team_count from ( select t.schedule_id, coalesce(nullif(t.team_code, ''), concat('NO_TEAM:', t.target_id)) as team_key, count(distinct t.target_id) as total_person_count, count(distinct signed.target_id) as signed_person_count from competition_scene_schedule s left join competition_series_info cs on cs.competition_series_id = s.competition_series_id and cs.del_flag = '0' inner join competition_scene_schedule_target t on t.schedule_id = s.schedule_id left join (
) signed on signed.schedule_id = t.schedule_id and signed.target_id = t.target_id where group by t.schedule_id, coalesce(nullif(t.team_code, ''), concat('NO_TEAM:', t.target_id)) ) tg group by tg.schedule_id ) team_count on team_count.schedule_id = v.schedule_id
and v.checkin_status = #{checkinStatus}
and v.warning_level != 'NORMAL'
and v.warning_level = #{warningLevel}

mapper.select:
select t.target_id, t.user_id, t.member_id, coalesce(signed.credential_id, credential.credential_id) as credential_id, t.team_code, coalesce(nullif(t.team_name, ''), '未分组') as team_name, t.user_name as person_name, 'MEMBER' as role_code, '队员' as role_name, case when signed.target_id is null then 'UNSIGNED' else 'SIGNED' end as checkin_status, signed.checkin_time, case when signed.target_id is null then null else 'REPORT' end as checkin_method from competition_scene_schedule_target t left join (
) signed on signed.schedule_id = t.schedule_id and signed.target_id = t.target_id left join (
) credential on credential.schedule_id = t.schedule_id and credential.target_id = t.target_id where t.schedule_id = #{scheduleId} and t.del_flag = '0' and t.status = '0' and t.match_status = 'MATCHED' and t.competition_role_name in ('队员', 'MEMBER', '选手', 'PLAYER')
and coalesce(nullif(t.team_code, ''), concat('NO_TEAM:', t.target_id)) = #{teamCode}
and ( t.user_name like concat('%', #{keyword}, '%') or t.team_name like concat('%', #{keyword}, '%') or t.team_code like concat('%', #{keyword}, '%') or t.certificate_code like concat('%', #{keyword}, '%') )
and signed.target_id is not null
and signed.target_id is null
order by t.team_name asc, t.sequence_no asc, t.target_id asc
